<?php
require_once $_SERVER['DOCUMENT_ROOT'] . '/bitrix/modules/main/include/prolog_before.php';
require_once $_SERVER['DOCUMENT_ROOT'] . '/local/sitebuilder/lib/auth.php';
sitebuilder_require_auth();

global $APPLICATION, $USER;
$basePath = rtrim(str_replace($_SERVER['DOCUMENT_ROOT'], '', __DIR__), '/');
$siteId = (int)($_GET['siteId'] ?? 0);
foreach ([__DIR__.'/lib/db.php',__DIR__.'/lib/json.php',__DIR__.'/lib/response.php',__DIR__.'/lib/helpers.php',__DIR__.'/lib/access.php'] as $file) require_once $file;
if (!$USER->IsAdmin()) {
    if ($siteId <= 0) { http_response_code(422); die('Не передан siteId.'); }
    sb_require_content_manager($siteId);
}
$isAdmin = $USER->IsAdmin();
$returnUrl = $siteId > 0 ? $basePath . '/settings.php?siteId=' . $siteId : $basePath . '/index.php';
?>
<!doctype html><html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SiteBuilder / Внешние ресурсы</title><?php $APPLICATION->ShowHead(); ?><link rel="stylesheet" href="<?=htmlspecialchars($basePath,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>/assets/admin/admin.css"><style>.resource-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(330px,.7fr);gap:16px}.resource-table{width:100%;border-collapse:collapse;min-width:980px}.resource-table th,.resource-table td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top}.status{display:inline-flex;padding:3px 8px;border-radius:999px;font-size:12px;font-weight:800}.attached{background:#dcfce7;color:#166534}.missing,.mismatched,.orphaned{background:#fee2e2;color:#991b1b}.cleanup_pending{background:#fef3c7;color:#92400e}.deleted{background:#e5e7eb;color:#374151}.run-list{display:grid;gap:8px}.run{padding:10px;border:1px solid #e5e7eb;border-radius:9px;cursor:pointer}.details{white-space:pre-wrap;word-break:break-word;max-height:52vh;overflow:auto}@media(max-width:1050px){.resource-grid{grid-template-columns:1fr}}</style></head><body class="sb-admin-body"><div class="sb-page">
<div class="sb-topbar"><div><a class="sb-back-link" href="<?=htmlspecialchars($returnUrl,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>">← Назад</a><h1 class="sb-title">Внешние ресурсы</h1><p class="sb-subtitle"><?= $siteId>0?'Сверка сайта #'.$siteId:'Глобальная сверка групп и папок SiteBuilder' ?></p></div><div class="sb-actions"><a class="sb-btn sb-btn-light" href="<?=htmlspecialchars($basePath,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')?>/alerts.php<?= $siteId>0?'?siteId='.$siteId:'' ?>">Оповещения</a><button class="sb-btn sb-btn-light" id="auditBtn">Запустить аудит</button><button class="sb-btn sb-btn-primary" id="repairBtn">Запустить repair</button><button class="sb-btn sb-btn-light" id="reloadBtn">Обновить</button></div></div>
<div id="message" class="sb-panel" style="display:none"></div><section class="sb-panel"><div class="sb-actions"><label class="sb-field"><span>Тип</span><select class="sb-select" id="type"><option value="">Все</option><option value="bitrix_group">Рабочие группы</option><option value="disk_folder">Папки Диска</option></select></label><label class="sb-field"><span>Состояние</span><select class="sb-select" id="status"><option value="">Все</option><option value="missing">Отсутствует</option><option value="mismatched">Не соответствует</option><option value="orphaned">Сирота</option><option value="cleanup_pending">Ожидает удаления</option><option value="attached">Привязан</option><option value="deleted">Удалён</option></select></label><button class="sb-btn sb-btn-primary" id="applyBtn">Применить</button></div></section>
<div class="resource-grid"><section class="sb-panel" style="overflow:auto"><table class="resource-table"><thead><tr><th>Тип / ID</th><th>Сайт</th><th>Состояние</th><th>Ожидалось</th><th>Фактически</th><th>Проверено</th><th></th></tr></thead><tbody id="rows"><tr><td colspan="7">Загрузка…</td></tr></tbody></table></section><aside><section class="sb-panel"><h2 class="sb-panel-title">Последние сверки</h2><div id="runs" class="run-list">Загрузка…</div></section><section class="sb-panel"><h2 class="sb-panel-title">Детали запуска</h2><pre id="detail" class="details">Выберите запуск</pre></section></aside></div>
</div><script>(function(){'use strict';var BASE='<?=CUtil::JSEscape($basePath)?>',SITE=<?=$siteId?>,ADMIN=<?=$isAdmin?'true':'false'?>,API=BASE+'/api.php';function sid(){return window.BX&&BX.bitrix_sessid?BX.bitrix_sessid():'<?=CUtil::JSEscape(bitrix_sessid())?>'}async function api(a,d){var r=await fetch(API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(Object.assign({action:a,sessid:sid()},d||{}))}),t=await r.text(),j;try{j=JSON.parse(t)}catch(e){throw{error:'BAD_JSON_RESPONSE'}}if(!j||j.ok!==true)throw j||{error:'UNKNOWN_ERROR'};return j}function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}function msg(t,e){var n=document.getElementById('message');n.style.display='block';n.style.color=e?'#991b1b':'#166534';n.textContent=t}async function loadResources(){var r=await api('external.resource.list',{siteId:SITE,resourceType:document.getElementById('type').value,status:document.getElementById('status').value,limit:300}),rows=r.items||[];document.getElementById('rows').innerHTML=rows.length?rows.map(function(x){var cleanup=ADMIN&&x.relationStatus==='orphaned'&&x.managed?'<button class="sb-btn sb-btn-light sb-btn-small cleanup" data-type="'+esc(x.resourceType)+'" data-id="'+Number(x.externalId)+'">Удалить сироту</button>':'';return '<tr><td>'+esc(x.resourceType)+'<br>#'+Number(x.externalId)+'</td><td>'+(x.siteId?'#'+Number(x.siteId):'—')+'</td><td><span class="status '+esc(x.relationStatus)+'">'+esc(x.relationStatus)+'</span></td><td>'+esc(x.expectedName||'—')+'</td><td>'+esc(x.actualName||'—')+'</td><td>'+esc(x.lastCheckedAt)+'</td><td>'+cleanup+'</td></tr>'}).join(''):'<tr><td colspan="7">Ресурсов пока нет. Запустите сверку.</td></tr>'}async function loadRuns(){var r=await api('external.reconcile.list',{siteId:SITE,limit:30}),rows=r.items||[];document.getElementById('runs').innerHTML=rows.length?rows.map(function(x){return '<div class="run" data-run="'+Number(x.id)+'"><strong>#'+Number(x.id)+' · '+esc(x.mode)+' · '+esc(x.status)+'</strong><br>'+esc(x.startedAt)+'<br>Проблем: '+Number(x.anomalies)+', исправлений: '+Number(x.repairs)+'</div>'}).join(''):'Запусков ещё нет'}async function load(){await Promise.all([loadResources(),loadRuns()])}async function enqueue(mode){var r=await api('external.reconcile.enqueue',{siteId:SITE,mode:mode}),j=r.job||{};msg('Сверка поставлена в очередь: #'+Number(j.id||0),false);return loadRuns()}document.addEventListener('click',function(e){var b=e.target.closest('.run');if(b)api('external.reconcile.get',{runId:Number(b.dataset.run)}).then(function(r){document.getElementById('detail').textContent=JSON.stringify(r.run||{},null,2)}).catch(function(x){msg(x.error||'Ошибка',true)});b=e.target.closest('.cleanup');if(b&&confirm('Поставить безопасное удаление ресурса в очередь?'))api('external.resource.cleanup',{resourceType:b.dataset.type,externalId:Number(b.dataset.id)}).then(function(r){msg('Задание очистки #'+Number((r.job||{}).id||0)+' создано',false);return load()}).catch(function(x){msg(x.error||'Ошибка',true)})});document.getElementById('auditBtn').onclick=function(){enqueue('audit').catch(function(x){msg(x.error||'Ошибка',true)})};document.getElementById('repairBtn').onclick=function(){enqueue('repair').catch(function(x){msg(x.error||'Ошибка',true)})};document.getElementById('reloadBtn').onclick=function(){load().catch(function(x){msg(x.error||'Ошибка',true)})};document.getElementById('applyBtn').onclick=function(){loadResources().catch(function(x){msg(x.error||'Ошибка',true)})};load().catch(function(x){msg(x.error||'Ошибка загрузки',true)});})();</script></body></html>
